from h import *
A = dict(id="A", levels=L1, kind="Leaflet", source="Ferndale Zoo", title="Adopt a panda", body=[
 {"p": "Help to look after the giant pandas at Ferndale Zoo by becoming a panda adopter. Ferndale Zoo is home to two giant pandas, who arrived last year. They love to eat, play and sleep in the sun."},
 {"box": "**Your adoption pack:** a certificate, a photo of your panda, a cuddly toy and a free family ticket."},
 {"p": "Adopting costs just £4 a month. Your money pays for the pandas' bamboo, health checks and toys. You can sign up at the zoo shop or online, and it only takes five minutes."}])
B = dict(id="B", levels=L1, kind="Magazine article", source="Wild Places magazine", title="How are giant pandas helped in the wild?", body=[
 {"p": "Giant pandas live in only a few mountain areas of China, and they depend on bamboo forests for food and shelter. Years ago, many of these forests were cleared to make room for farms and new buildings. As the forests shrank, the pandas lost their homes."},
 {"h": "Protected reserves"},
 {"p": "To help the pandas, China has set up protected nature reserves, where trees cannot be cut down. There are now dozens of reserves across the mountains, and together they protect large areas of forest. Rangers walk through the forests every week to check on the wildlife. They look for paw prints and droppings, and they also place cameras that take photographs when an animal walks past."},
 {"h": "Joining the forests together"},
 {"p": "Many pandas now live in small patches of forest that are cut off from each other. The corridors – strips of forest that join one area to another – allow pandas to move safely between patches, so that they can find food and meet mates. Planting new bamboo along the corridors takes years, but the forest is slowly joining up again. \"Without the corridors, the pandas would be trapped,\" says ranger Li Na."},
 {"h": "How can zoos help?"},
 {"p": "Zoos cannot return pandas to the wild by themselves, but they can still make a difference. Money raised by zoos and their visitors helps to pay for the reserves and the rangers. Zoos also run breeding programmes, so that scientists can learn how to care for baby pandas. Visitors can also help by adopting a panda, which pays for food and care."},
 {"h": "A success story"},
 {"p": "Conservation work takes many years, and it is not easy. Even so, the work to save the giant panda is the most inspiring conservation story of recent times. Nothing is more important than protecting the forests where these animals live."}])
C = dict(id="C", levels=L1, kind="School newsletter article", source="Ferndale High School newsletter", title="Our class adopted a panda. Will you?", body=[
 {"p": "Last term, Year 10 voted to adopt a giant panda. Why? In geography we learned that pandas are losing their forest homes, and we wanted to do something about it."},
 {"p": "Imagine a world without pandas. Some people ask why we should care about animals so far away. We believe that every living thing matters, and pandas are a symbol of hope for nature all over the world. Would you want a world without them? Of course not! Every pound we raise helps to pay for bamboo, health checks and toys, so it really does make a difference."},
 {"p": "We have already raised £86 from our cake sale, but we need your help to reach £200 by the end of term. Our teacher, Mr Dale, thinks we can do it, and we are determined to prove him right. It will be fun, and you will be helping a great cause."},
 {"p": "Here is how you can help:"},
 {"ul": ["Donate any amount at the school office.", "Join our sponsored silent hour on Friday.", "Bake something for our second cake sale."]},
 {"p": "Just £2 buys a day's bamboo for one panda, so please give whatever you can. Together, we can help to protect these amazing animals!"}])

